<?php
class AuthController extends Controller {public function login():void{if(Auth::check())$this->redirect('dashboard');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$u=(new Usuario())->authenticate(trim($_POST['username']??''),$_POST['password']??'');if($u){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id_usuario'],'nombre'=>$u['nombres'],'rol'=>$u['rol']];$this->redirect('dashboard');}$error='Usuario o contraseña incorrectos.';}$this->view('auth/login',compact('error')+['title'=>'Ingresar']);}public function logout():void{$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']);}session_destroy();header('Location: '.BASE_URL.'/auth/login');exit;}}

